from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
revision='e8a58465bcab87b2b12f59a2d3d63de5cfd8bb79'
os.environ['PYTHONPATH']=str(code/'src')+':'+str(code)
sys.path[:0]=[str(code/'src'),str(code)]
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
(out/'runner_provenance.json').write_text(json.dumps(dict(seed=20261013,git_commit=revision,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),scope='fixed source1 computation timing only; no sealed data'),indent=2))
subprocess.run([sys.executable,'-m','pip','install','pytest','pyarrow','statsmodels'],check=True)
